<?php declare(strict_types=1);namespace StudPulse\Security;use StudPulse\Database\DB;use StudPulse\Http\ApiError;final class RateLimit{public static function check(string$bucket,int$max,int$seconds=60):void{$window=intdiv(time(),$seconds)*$seconds;$key=Crypto::hash($bucket);DB::run('INSERT INTO rate_limits(bucket,window_start,hits) VALUES(?,?,1) ON DUPLICATE KEY UPDATE hits=hits+1',[$key,$window]);$row=DB::one('SELECT hits FROM rate_limits WHERE bucket=? AND window_start=?',[$key,$window]);if((int)$row['hits']>$max){throw new ApiError(429,'RATE_LIMITED','Слишком много запросов. Попробуйте позже.',['retryAfter'=>$window+$seconds-time()]);}}}